describe('ML-DSA-keyGen-FIPS204 (NIST CAVP, 9 sub-samples / 75 total)', () => {
    test.each(_KG_DSA)(
        'tgId=$tg tcId=$tc ($ps): keygen(seed) == (pk, sk)',
        (v) => {
            const kp = _MLDSA[v.ps].keygen(_hex.toBytes(v.seed));
            expect(kp).not.toBe(false);
            expect(_hex.fromBytes(kp.publicKey)).toBe(v.pk.toLowerCase());
            expect(_hex.fromBytes(kp.secretKey)).toBe(v.sk.toLowerCase());
        },
        60_000
    );
});

describe('ML-DSA-sigGen-FIPS204 / external+pure (NIST CAVP, 18 sub-samples)', () => {
    test.each(_SG_DSA)(
        'tgId=$tg tcId=$tc ($ps, deterministic=$det): sign(msg, sk, ctx, rnd) == signature',
        (v) => {
            const sk  = _hex.toBytes(v.sk);
            const msg = _hex.toBytes(v.msg);
            const ctx = v.ctx ? _hex.toBytes(v.ctx) : new Uint8Array(0);
            const rnd = v.det ? new Uint8Array(32) : _hex.toBytes(v.rnd);
            const sig = _MLDSA[v.ps].sign(msg, sk, ctx, rnd);
            expect(sig).not.toBe(false);
            expect(_hex.fromBytes(sig)).toBe(v.sig.toLowerCase());
        },
        90_000
    );
});

describe('ML-DSA-sigVer-FIPS204 / external+pure (NIST CAVP, 45/45 vectors)', () => {
    test.each(_SV_DSA)(
        'tgId=$tg tcId=$tc ($ps, expected=$pass, reason=$reason): verify(sig, msg, pk, ctx)',
        (v) => {
            const pk  = _hex.toBytes(v.pk);
            const msg = _hex.toBytes(v.msg);
            const sig = _hex.toBytes(v.sig);
            const ctx = v.ctx ? _hex.toBytes(v.ctx) : new Uint8Array(0);
            const ok = _MLDSA[v.ps].verify(sig, msg, pk, ctx);
            expect(ok).toBe(v.pass);
        },
        60_000
    );
});


// ============================================================================
// ML-DSA HashML-DSA + internal + externalMu - iteration E3 of the upgrade plan
// ----------------------------------------------------------------------------
// Sources:
//   ML-DSA-sigGen-FIPS204 / external+preHash det=true (3 paramSets × 3 sub-samples = 9)
//   ML-DSA-sigGen-FIPS204 / internal det=true (3 × 3 = 9)
//   ML-DSA-sigGen-FIPS204 / externalMu det=true (3 × 3 = 9)
//   ML-DSA-sigVer-FIPS204 / external+preHash (3 × 15 = 45 mix valid/invalid)
//
// API tested:
//   - signPh(msg, sk, hashAlg, hashMod, ctx, rnd=null) - HashML-DSA
//   - verifyPh(sig, msg, pk, hashAlg, hashMod, ctx)
//   - _internal.signInternal(M, sk, rnd=null) - §6.2 raw path (no §5.4 wrapper)
//   - _internal.signWithMu(mu, sk, rnd=null) - externalMu (pre-computed mu)
// ============================================================================

